#!/usr/bin/env bash
# Fails when a tracked file silences a linter, scanner, type checker, coverage or mutation tool, a
# runtime warning or a test, or escapes the type system. Inline suppressions are forbidden everywhere
# in this repository (see CONTRIBUTING.md): fix the cause, or configure the rule narrowly in the
# tool's own configuration file with the reason next to it.
#
# Not scanned: Markdown (it documents these rules), this script (it names the patterns), and dist/
# (generated by ncc from src/ and node_modules/, so it carries the comments of third-party code; CI
# proves it is a byte-identical rebuild of src/).
set -euo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")/.."

files=$(git ls-files -z -- . ':(exclude)*.md' ':(exclude)script/forbidden_suppressions.sh' ':(exclude)dist/' \
  | tr '\0' '\n')

status=0
check() {
  local description=$1 pattern=$2 scope=${3:-}
  local hits
  hits=$(printf '%s\n' "${files}" | grep -E "^${scope}" | xargs -r grep -nEH -e "${pattern}" -- || true)
  if [[ -n "${hits}" ]]; then
    printf 'Forbidden (%s):\n%s\n\n' "${description}" "${hits}"
    status=1
  fi
}

check 'ESLint directive' 'eslint-(disable|enable)|/\*[[:space:]]*(eslint|global|exported)[[:space:]]'
check 'TypeScript suppression' '@ts-(ignore|expect-error|nocheck)'
check 'any type' '\bas any\b|:[[:space:]]*any[[:space:]]*([],;)=|&>]|$)|<any>|\bany\[\]'
check 'double cast' 'as unknown as'
check 'non-null assertion' '[[:alnum:]_)\]]![.;,)[:space:]]' '(src|__tests__|script)/'
check 'coverage exclusion' '(istanbul|c8|v8)[[:space:]]+ignore'
check 'Stryker suppression' 'Stryker[[:space:]]+(disable|restore)'
check 'Prettier suppression' 'prettier-ignore'
check 'Markdown lint suppression' '(markdownlint|rumdl)-(disable|enable|capture|restore|configure-file)'
check 'jscpd suppression' 'jscpd:ignore'
check 'gitleaks allow' 'gitleaks:allow'
check 'zizmor ignore' 'zizmor: ?ignore'
check 'shellcheck disable' 'shellcheck +disable'
check 'LGTM/CodeQL suppression' 'lgtm\[|codeql\[|codeql-disable|lgtm: ?ignore'
check 'nosec' 'nosec'
check 'warning silencing' '--no-warnings|--no-deprecation|--disable-warning|NODE_NO_WARNINGS|noDeprecation|removeAllListeners\(.warning|dangerouslyIgnoreUnhandledErrors|onConsoleLog'
check 'skipped or focused test' '\b(it|test|describe|suite|bench)\.(skip|only|todo|fails|skipIf|runIf)\b|\b(xit|xtest|xdescribe|fit|fdescribe)\(' '__tests__/'

exit "${status}"
